update public.contenu_site set valeur = (select jsonb_agg(case when e->>'slug' = 'temple-des-pythons' and e->>'name' = $t$Temple des Pythons$t$ then jsonb_set(e, '{name}', to_jsonb($t$Pythontempel$t$::text)) else e end order by i) from jsonb_array_elements(valeur) with ordinality as x(e, i)) where cle = 'DE:fr.places' and jsonb_typeof(valeur) = 'array' and exists (select 1 from jsonb_array_elements(valeur) as y(e) where e->>'slug' = 'temple-des-pythons' and e->>'name' = $t$Temple des Pythons$t$);
